using System;using System.IO;using UnityEngine;using UnityEditor;
public static class CourtyardPaintMeshAudit {
 static float S(float a,float b,float x){float t=Mathf.Clamp01((x-a)/(b-a));return t*t*(3-2*t);}
 public static void ApplyDiagnostic(GameObject root){if(Environment.GetEnvironmentVariable("LIGHTFIGHT_PAINT_MASK_DEBUG")!="1")return;foreach(var r in root.GetComponentsInChildren<Renderer>())if(r.name.StartsWith("Photo ")){var block=new MaterialPropertyBlock();r.GetPropertyBlock(block);block.SetFloat("_MaskDiagnostic",1);r.SetPropertyBlock(block);}}
 public static void Run(){const string d="Assets/LighFight/Art/Drafts/ComponentCourtyardReview";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(d+"/source-sedan.mesh.asset");var mat=AssetDatabase.LoadAssetAtPath<Material>(d+"/sedan-0.mat");var tex=new Texture2D(2,2,TextureFormat.RGBA32,false,true);try{if(!tex.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(mat.GetTexture("_MainTex")))))throw new Exception("Originalcolor read failed");var v=mesh.vertices;var uv=mesh.uv;int body=0,bodyHit=0,window=0,windowHit=0,wheel=0,wheelHit=0;for(int i=0;i<v.Length;i+=17){var p=v[i];var c=tex.GetPixelBilinear(uv[i].x,uv[i].y);float l=.2126f*c.r+.7152f*c.g+.0722f*c.b;float m=S(.012f,.055f,c.b-c.r)*S(.025f,.09f,Mathf.Max(c.r,Mathf.Max(c.g,c.b))-Mathf.Min(c.r,Mathf.Min(c.g,c.b)))*S(.025f,.08f,l);m*=1-S(1.16f,1.23f,p.y)*(1-S(1.72f,1.82f,p.y));float distance=Mathf.Min(new Vector2(p.z-1.4f,p.y-.5f).magnitude,new Vector2(p.z+1.4f,p.y-.5f).magnitude);m*=Mathf.Lerp(1,S(.43f,.56f,distance),S(.55f,.75f,Mathf.Abs(p.x)));if(p.y>=1.23f&&p.y<=1.72f){window++;if(m>.1f)windowHit++;}else if(Mathf.Abs(p.x)>.75f&&distance<.43f){wheel++;if(m>.1f)wheelHit++;}else if((p.y>.7f&&p.y<1.16f&&Mathf.Abs(p.z)<1)||p.y>1.82f){body++;if(m>.5f)bodyHit++;}}
 Directory.CreateDirectory("CourtyardPaintAudit");File.WriteAllText("CourtyardPaintAudit/mesh-mask.json","{\"sourceVertexUvSamplesStep\":17,\"bodyCandidateSamples\":"+body+",\"bodyMaskAboveHalf\":"+bodyHit+",\"windowProtectedSamples\":"+window+",\"windowMaskAbovePointOne\":"+windowHit+",\"wheelProtectedSamples\":"+wheel+",\"wheelMaskAbovePointOne\":"+wheelHit+",\"semanticRegionsInferred\":true,\"gpuVerified\":false}");if(bodyHit==0)throw new Exception("No bodycandidate coverage; reject mask");if(windowHit!=0||wheelHit!=0)throw new Exception("Protectedregion leakage; reject mask");Debug.Log("AGENT_RESULT actualsourcevertexUV mask audit: body="+bodyHit+"/"+body+" protectedwindow/wheel zero leakage; regions inferred, GPUpending");}finally{UnityEngine.Object.DestroyImmediate(tex);}}
}
